-- Social prototype: private messages, friend requests, blocks, reports and activity invitations.
create table public.campus_blocks (blocker uuid not null references auth.users on delete cascade, blocked uuid not null references auth.users on delete cascade, created_at timestamptz not null default now(), primary key(blocker,blocked), check(blocker <> blocked));
alter table public.campus_blocks enable row level security;
create policy "manage own blocks" on public.campus_blocks for all to authenticated using (blocker=auth.uid()) with check (blocker=auth.uid());
grant select,insert,delete on public.campus_blocks to authenticated;
create function public.campus_blocked(a uuid,b uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select case when auth.uid() not in (a,b) then true else exists(select 1 from public.campus_blocks where (blocker=a and blocked=b) or (blocker=b and blocked=a)) end $$;
revoke all on function public.campus_blocked(uuid,uuid) from public;
grant execute on function public.campus_blocked(uuid,uuid) to authenticated;
create table public.campus_friendships (id bigint generated always as identity primary key, sender uuid not null references auth.users on delete cascade, recipient uuid not null references auth.users on delete cascade, state text not null default 'pending' check(state in ('pending','accepted')), created_at timestamptz not null default now(), check(sender<>recipient));
create unique index campus_friend_pair on public.campus_friendships (least(sender,recipient),greatest(sender,recipient));
alter table public.campus_friendships enable row level security;
create policy "participants see friendships" on public.campus_friendships for select to authenticated using (auth.uid() in (sender,recipient));
create policy "send friend request" on public.campus_friendships for insert to authenticated with check (auth.uid()=sender and state='pending' and not public.campus_blocked(sender,recipient));
create policy "respond to friend request" on public.campus_friendships for update to authenticated using (recipient=auth.uid() and state='pending') with check (recipient=auth.uid() and state='accepted');
create policy "remove friendship" on public.campus_friendships for delete to authenticated using (auth.uid() in (sender,recipient));
grant select,insert,delete on public.campus_friendships to authenticated;
grant update(state) on public.campus_friendships to authenticated;
create table public.campus_messages (id bigint generated always as identity primary key,sender uuid not null references auth.users on delete cascade,recipient uuid not null references auth.users on delete cascade, body text not null check(char_length(trim(body)) between 1 and 200),created_at timestamptz not null default now(),check(sender<>recipient));
alter table public.campus_messages enable row level security;
create policy "participants read messages" on public.campus_messages for select to authenticated using (auth.uid() in (sender,recipient));
create policy "send message" on public.campus_messages for insert to authenticated with check (sender=auth.uid() and not public.campus_blocked(sender,recipient));
grant select,insert on public.campus_messages to authenticated;
create table public.campus_invitations (id bigint generated always as identity primary key,sender uuid not null references auth.users on delete cascade,recipient uuid not null references auth.users on delete cascade, activity text not null check(activity in ('Meet at the Globe','Hang out at the Rock','Meet at the Recreation Center')), state text not null default 'pending' check(state in ('pending','accepted','declined')),created_at timestamptz not null default now(),check(sender<>recipient));
alter table public.campus_invitations enable row level security;
create policy "participants read invites" on public.campus_invitations for select to authenticated using (auth.uid() in (sender,recipient));
create policy "send invite" on public.campus_invitations for insert to authenticated with check (sender=auth.uid() and state='pending' and not public.campus_blocked(sender,recipient));
create policy "respond to invite" on public.campus_invitations for update to authenticated using (recipient=auth.uid() and state='pending') with check (recipient=auth.uid() and state in ('accepted','declined'));
grant select,insert on public.campus_invitations to authenticated;
grant update(state) on public.campus_invitations to authenticated;
create table public.campus_reports (id bigint generated always as identity primary key, reporter uuid not null references auth.users on delete cascade, reported uuid not null references auth.users on delete cascade,reason text not null check(char_length(trim(reason)) between 1 and 500),created_at timestamptz not null default now(),check(reporter<>reported));
alter table public.campus_reports enable row level security;
create policy "submit own report" on public.campus_reports for insert to authenticated with check (reporter=auth.uid());
grant insert on public.campus_reports to authenticated;
